package com.example.sumayerestaurant.ui.reservation;
import android.app.*;import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.sumayerestaurant.data.api.RetrofitClient;import com.example.sumayerestaurant.data.local.TokenManager;import com.example.sumayerestaurant.data.model.*;import java.time.*;import java.util.*;import retrofit2.*;
/** Simple reservation form. The server is the final authority for availability and capacity. */
public class ReservationActivity extends AppCompatActivity{private Long branchId;private EditText customer,guests,date,start,end,notes;private Spinner tables;@Override public void onCreate(Bundle b){super.onCreate(b);User u=new TokenManager(this).getUser();branchId=(u==null||u.getBranchId()==null)?1L:u.getBranchId();setTitle("Uhifadhi wa Meza");LinearLayout root=new LinearLayout(this);root.setPadding(32,32,32,32);root.setOrientation(LinearLayout.VERTICAL);customer=f("ID ya mteja");date=f("Tarehe (YYYY-MM-DD)");date.setText(LocalDate.now().toString());start=f("Muda wa kuanza (HH:MM)");end=f("Muda wa kuondoka (HH:MM)");guests=f("Idadi ya watu");tables=new Spinner(this);notes=f("Maelezo (si lazima)");root.addView(customer);root.addView(date);root.addView(start);root.addView(end);root.addView(guests);root.addView(tables);root.addView(notes);Button save=new Button(this);save.setText("Thibitisha Uhifadhi");root.addView(save);setContentView(root);save.setOnClickListener(v->confirm());loadTables();}private EditText f(String h){EditText e=new EditText(this);e.setHint(h);e.setMinHeight(88);return e;}private void loadTables(){if(branchId==null)return;RetrofitClient.getApiService(this).getTables(branchId).enqueue(new Callback<List<RestaurantTable>>(){public void onResponse(Call<List<RestaurantTable>>c,Response<List<RestaurantTable>>r){if(r.isSuccessful()&&r.body()!=null)tables.setAdapter(new ArrayAdapter<>(ReservationActivity.this,android.R.layout.simple_spinner_dropdown_item,r.body()));else toast("Imeshindikana kupakia meza.");}public void onFailure(Call<List<RestaurantTable>>c,Throwable t){toast("Hakuna mtandao.");}});}private void confirm(){if(customer.getText().toString().isEmpty()||guests.getText().toString().isEmpty()||tables.getSelectedItem()==null){toast("Jaza mteja, muda, idadi ya watu na meza.");return;}new AlertDialog.Builder(this).setMessage("Una uhakika unataka kuthibitisha uhifadhi huu?").setNegativeButton("Ghairi",null).setPositiveButton("Endelea",(d,w)->save()).show();}private void save(){try{RestaurantTable t=(RestaurantTable)tables.getSelectedItem();Map<String,Object>x=new HashMap<>();x.put("customerId",Long.parseLong(customer.getText().toString()));x.put("tableId",t.getId());x.put("reservationDate",date.getText().toString());x.put("startTime",start.getText().toString());x.put("endTime",end.getText().toString());x.put("guestCount",Integer.parseInt(guests.getText().toString()));x.put("notes",notes.getText().toString());RetrofitClient.getApiService(this).createReservation(branchId,x).enqueue(new Callback<Object>(){public void onResponse(Call<Object>c,Response<Object>r){if(r.isSuccessful()){toast("Uhifadhi umehifadhiwa.");finish();}else toast("Meza haipatikani au taarifa si sahihi.");}public void onFailure(Call<Object>c,Throwable t){toast("Hakuna mtandao. Tafadhali jaribu tena.");}});}catch(Exception e){toast("Weka tarehe, muda na idadi sahihi.");}}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}}
